#include <bits/stdc++.h>using namespace std;int solve(string s){    int n = s.length();    int ans = 0;        int count=0;     int maxi = 0;     for(int i = 0 ;i < n ;i++){        int j = i;        if(s[i] == '.'){            while( j < n && s[i] == s[j]){                j++;            }            maxi = max(maxi,j-i);            ans += ( j-i > 2 ? 2 : (j-i));        }        i = j;    }       return maxi > 2 ? 2 : ans ;}  int main() {	// your code goes here	int T ;	cin >> T ; 		while(T --){	    int n ; 	    cin >> n ;	    	    string s;	    cin >> s;	    	    cout << solve(s) << endl;	}     return 0;}